from phonekit import *
from v9_common import run
ep=Ep()
notes(ep,0,8.4,'22:10','Что я узнала за 7 лет с ребёнком-бабочкой 🦋',['1. Обычный пластырь — нельзя. Никогда.','2. Повязки — только нелипкие, на силиконовой основе.','3. Каждое снятие — медленно. Каждое.','4. Перевязки — часть каждого дня. Мы научились.','5. Обнимать — бережно. Но обязательно 🤍'],step=1.1,light=True)
ep.body+=f'<div class="clip" data-start="0" data-duration="2.8" data-track-index="2">{caption("hc","Мой сын —<br><span style=\"color:#F38221\">«ребёнок-бабочка».</span>",1480)}</div>'
ep.js+='tl.from("#hc",{opacity:0,y:30,duration:.4},.1).to("#hc",{opacity:0,duration:.4},2.4);'
