chat(ep,8.4,7.6,'22:24','Света','С',[('them','Прочитала твой пост… Я не знала, что такое вообще бывает 😢',.3),('them','Как я могу помочь?',2.0),('me','Просто расскажи о детях-бабочках. 25–31 октября — их неделя 🦋',3.6),('them','Уже репощу. И в рабочий чат отправила ❤️',5.6)],typing_before=(3,))
endcard(ep,16.0,5.0,'Есть дети, чья кожа хрупкая,','как крыло бабочки.','🦋 25–31 октября — неделя детей-бабочек<br>Поделитесь, чтобы о них узнали','Сценка по мотивам рекомендаций DEBRA и GOSH. Медицинское изделие. Применение — по назначению специалиста.')
run('e4_dermatologiya_deti_babochki',ep,21.0,'Дети-бабочки',check=(5.0,1.2,12.5,18.5),pad=(103.8,155.6,207.7))
